sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    var incidentSysId = request.body.data.incident_sysid;
    var incidentGr = new GlideRecord('incident');
    if (incidentGr.get(incidentSysId)) {
        var requestorPhone = incidentGr.caller_id.phone.toString();

        // Call the AI tool (Twilio + OpenAI)
        var aiResponse = callAIAndGetResponse(requestorPhone);

        if (aiResponse === 'yes') {
            incidentGr.state = 6; // Close the incident
            incidentGr.close_notes = 'Incident closed based on requestor\'s confirmation over the call.';
            incidentGr.update();
            return { status: 'success', message: 'Incident closed.' };
        } else {
            return { status: 'success', message: 'Incident remains open.' };
        }
    } else {
        return { status: 'error', message: 'Incident not found.' };
    }
})(request, response);
